mapper.select:
SELECT CD.*, CI.CustName AS CustName
FROM shopion.tPrfCustDeliAddr CD
INNER JOIN shopion.tPrfCust CI ON CD.CustId = CI.CustId

    AND CI.ChnlCode = #{pChnlCode}
    AND CI.CustName LIKE CONCAT('%',#{pCustName},'%')
    AND CI.LoginId LIKE CONCAT('%',#{pLoginId},'%')
    AND CI.CustId = #{pCustId}

ORDER BY ${sidx} ${sord}

SELECT *
FROM shopion.tPrfCustDeliAddr
WHERE CustId = #{custId}
AND DeliAddrNo = #{deliAddrNo}

mapper.insert:
INSERT INTO shopion.tPrfCustDeliAddr (
    CustId, DefaltYn, RecverName, Zipcode, Addr1, Addr2,
    HomePhoneNo, MobilePhoneNo, MobileSvc, ChnlCode,
    State, Remark, RegistDate, RegistId, RegistName
) VALUES (
    #{custId}, #{defaltYn}, #{recverName}, #{zipcode}, #{addr1}, #{addr2},
    #{homePhoneNo}, #{mobilePhoneNo}, #{mobileSvc}, #{chnlCode},
    #{state}, #{remark}, NOW(), #{registId}, #{registName}
)

mapper.update:
UPDATE shopion.tPrfCustDeliAddr SET
    DefaltYn = #{defaltYn}, RecverName = #{recverName}, Zipcode = #{zipcode},
    Addr1 = #{addr1}, Addr2 = #{addr2}, HomePhoneNo = #{homePhoneNo},
    MobilePhoneNo = #{mobilePhoneNo}, MobileSvc = #{mobileSvc},
    ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}
WHERE CustId = #{custId}
AND DeliAddrNo = #{deliAddrNo}

UPDATE shopion.tPrfCustDeliAddr SET
    DefaltYn = 0, ChangeDate = NOW()
WHERE CustId = #{value}

mapper.delete:
DELETE FROM shopion.tPrfCustDeliAddr
WHERE CustId = #{custId}
AND DeliAddrNo = #{deliAddrNo}
